using System;using System.Collections.Generic;
namespace UnityEngine.Events {public delegate void UnityAction();}
public enum MetaType {None}
public delegate object TooltipDataGetter();
public class KeyValueField {public UnityEngine.Events.UnityAction on_click_value;public string value;}
public class StatsWindow {public Dictionary<string,KeyValueField> rows=new Dictionary<string,KeyValueField>();protected KeyValueField showStatRow(string label,object value,string icon,MetaType meta,long id,bool flag,string str1,string str2,TooltipDataGetter getter,bool flag2){KeyValueField row;if(!rows.TryGetValue(label,out row)){row=new KeyValueField();rows[label]=row;}row.value=value.ToString();return row;}public virtual void updateStats(){}}
public class CityWindow:StatsWindow {public City selected;public City getMetaObject(){return selected;}public override void updateStats(){NativeEconomyUI.ShowCity(this);}}
public class KingdomWindow:StatsWindow {public Kingdom selected;public Kingdom getMetaObject(){return selected;}}
public class FamilyWindow:StatsWindow {public Family selected;public Family getMetaObject(){return selected;}}
public class UnitWindow:StatsWindow {public Actor selected;protected Actor get_actor(){return selected;}}
namespace UnityEngine {public static class Debug {public static List<string> warnings=new List<string>();public static void LogWarning(object s){warnings.Add(s.ToString());}}}
public class BaseSystemData {public long id;readonly Dictionary<string,object> values=new Dictionary<string,object>();public void get(string k,out string v,string d){object x;v=values.TryGetValue(k,out x)?(string)x:d;}public void get(string k,out int v,int d){object x;v=values.TryGetValue(k,out x)?(int)x:d;}public void get(string k,out long v,long d){object x;v=values.TryGetValue(k,out x)?(long)x:d;}public void set(string k,string v){values[k]=v;}public void set(string k,int v){values[k]=v;}public void set(string k,long v){values[k]=v;}}
public class SaveCustomData:BaseSystemData {}public class CityData:BaseSystemData{public long kingdomID;}public class ActorData:BaseSystemData {public int money,loot;}public class FamilyData:BaseSystemData {}public class KingdomData:BaseSystemData{}public class WarData:BaseSystemData{}
public class MapStats {public int year;public SaveCustomData custom_data=new SaveCustomData();}public class MapBox {internal MapStats map_stats=new MapStats();public CityManager cities=new CityManager();}public static class World {public static MapBox world=new MapBox();}public class CityManager {public List<City> list=new List<City>();}
public class BaseStats {public float this[string key]{get{return 10;}}}public class BaseSimObject{internal BaseStats stats=new BaseStats();}
public class Actor:BaseSimObject {internal ActorData data=new ActorData();public Family family;public City city;public bool alive=true,baby,warrior;public int experience;public List<Actor> children=new List<Actor>();public ActorData getData(){return data;}public bool isAlive(){return alive;}internal void addExperience(int x){experience+=x;}public City getCity(){return city;}public bool isBaby(){return baby;}public bool is_profession_warrior{get{return warrior;}}public void spendMoney(int n){data.money-=n;}public void addLoot(int n){data.loot=GodWorldRuntime.SaturatingResourceSum(data.loot,n);}public bool isKing(){return false;}public bool isCityLeader(){return false;}public bool changeHappiness(string k,int a){return true;}public IEnumerable<Actor> getChildren(bool unused){return children;}}
public class Family {public FamilyData data=new FamilyData();public List<Actor> units=new List<Actor>();}
public class Culture {public HashSet<string> traits=new HashSet<string>();public bool addTrait(string s,bool b){return traits.Add(s);}}
public class Kingdom {public KingdomData data=new KingdomData();public List<War> wars=new List<War>();public List<City> cities=new List<City>();public City capital;public Actor king;public Culture culture=new Culture();public IEnumerable<War> getWars(bool b){return wars;}public void setCapital(City c){capital=c;}}
public class CityStatus{public int population,population_adults,warrior_slots;}
public class City {public CityData data=new CityData();internal Kingdom kingdom;internal float timer_build=10;internal float _timer_warrior=10;public float timer_action=10;public CityStatus status=new CityStatus();public Actor leader;public List<Actor> units=new List<Actor>();public int buildings=3,soldiers;public Dictionary<string,int> resources=new Dictionary<string,int>();public bool alive=true;public bool isAlive(){return alive;}public bool isCapitalCity(){return kingdom!=null&&kingdom.capital==this;}public int getPopulationPeople(){return status.population;}public int getResourcesAmount(string r){int n;resources.TryGetValue(r,out n);return GodWorldRuntime.ResourceTotal(this,r,n);}public void takeResource(string r,int n){n=GodWorldRuntime.DrainReserve(this,r,n);int old;resources.TryGetValue(r,out old);resources[r]=Math.Max(0,old-n);}public int addResourcesToRandomStockpile(string r,int n){int old;resources.TryGetValue(r,out old);resources[r]=GodWorldRuntime.SaturatingResourceSum(old,n);return resources[r];}public int countWarriors(){return soldiers;}public int countBuildings(){return buildings;}public bool hasLeader(){return leader!=null;}public void removeLeader(){leader=null;}}
public class WarTypeAsset {public bool rebellion;}public class War {public WarData data=new WarData();public bool ended;public Kingdom attacker;public WarTypeAsset asset=new WarTypeAsset();public bool hasEnded(){return ended;}public WarTypeAsset getAsset(){return asset;}public bool isMainAttacker(Kingdom k){return k==attacker;}public Kingdom getMainAttacker(){return attacker;}public void lostWar(Kingdom k){ended=true;}}
public class EquipmentAsset {public string material;}public class ResourceAsset {public int maximum,storage_max;}public class ResourceLibrary {public List<ResourceAsset> list=new List<ResourceAsset>();}public class CityResources {public Dictionary<string,int> amounts=new Dictionary<string,int>();public int get(string s){int n;return amounts.TryGetValue(s,out n)?n:0;}}public class ConstructionCost{public int wood,stone,common_metals,gold;}
public static class MapSizeLibrary {public static object getPresetAsset(int n){return n>0?new object():null;}}
class RuntimeTests {
 static int checks;static void Check(bool ok,string label){if(!ok)throw new Exception(label);checks++;Console.WriteLine("PASS "+label);}
 static City City(long id,int p){var k=new Kingdom();k.data.id=id;var c=new City();c.data.id=id;c.data.kingdomID=id;c.kingdom=k;k.capital=c;k.cities.Add(c);c.status.population=c.status.population_adults=p;World.world.cities.list.Add(c);return c;}
 static void Main(){var c=City(1,100);c.resources["wood"]=10000;c.resources["stone"]=10000;c.resources["common_metals"]=10000;
  GodWorldRuntime.Issue(c,false,1000);GodWorldRuntime.Issue(c,true,100);Check(GodWorldRuntime.GetGold(c)==1000&&GodWorldRuntime.GetGod(c)==100,"native bank balances");
  GodWorldRuntime.SetRate(2.3);double before=GodWorldRuntime.GetGold(c)+GodWorldRuntime.GetGod(c)*2.3;GodWorldRuntime.Exchange(c,false,1);Check(Math.Abs(GodWorldRuntime.GetGold(c)+GodWorldRuntime.GetGod(c)*2.3-before)<.00001,"fractional exchange conservation");
  c.takeResource("gold",40);Check(GodWorldRuntime.GetGold(c)==962,"native expense drains bank reserve");double old=GodWorldRuntime.GetGold(c);GodWorldRuntime.Issue(c,false,-1e9);Check(GodWorldRuntime.GetGold(c)==old,"over-burn rejected atomically");
  var a=new Actor{city=c};a.data.money=0;c.units.Add(a);int wage=GodWorldRuntime.FundNativeIncome(a,10);a.data.money+=wage;Check(wage==10&&GodWorldRuntime.GetGold(c)==old-10,"wage transfers city gold");GodWorldRuntime.SpendCommerce(a,100);Check(a.data.money==0,"consumer never spends negative");
  int woodBefore=c.getResourcesAmount("wood");World.world.map_stats.year=1;GodWorldRuntime.TickCity(c,1);Check(c.getResourcesAmount("wood")<woodBefore,"growth consumes real native resources");int after=c.getResourcesAmount("wood");GodWorldRuntime.TickCity(c,1);Check(c.getResourcesAmount("wood")==after,"exactly one annual tick");
  int xp=NativeProgression.SkillLevel(a,0);GodWorldRuntime.Deliver(c,"wood",500,a);Check(NativeProgression.SkillLevel(a,0)>=xp,"successful work has persistent skill");
  var f=new Family();a.family=f;var heir=new Actor{family=f,city=c};f.units.Add(a);f.units.Add(heir);a.children.Add(heir);a.data.money=73;GodWorldRuntime.BeforeDeath(a);Check(a.data.money==0&&heir.data.money==73,"descendant inherits without duplication");
  var rc=new CityResources();rc.amounts["wood"]=int.MaxValue-10;Check(GodWorldRuntime.SafeResourceDelta(rc,"wood",100)==10,"resource overflow bounded");Check(GodWorldRuntime.SafeResourceDelta(rc,"wood",int.MinValue)==-(int.MaxValue-10),"resource withdrawal nonnegative");
  var rebel=City(2,6);var w=new War{attacker=rebel.kingdom};w.asset.rebellion=true;rebel.kingdom.wars.Add(w);RebellionRules.CheckDefeat(w);Check(!w.ended,"origin district six continues");rebel.status.population=5;RebellionRules.CheckDefeat(w);Check(w.ended,"origin district five fails");
  GodWorldRuntime.Flush();var retained=World.world.map_stats.custom_data;World.world.map_stats=new MapStats{year=1,custom_data=retained};Check(GodWorldRuntime.GetRate()==2.3,"rate follows saved world");Check(GodWorldRuntime.GetGod(c)>0,"god reload survives cache reset");
  var window=new CityWindow{selected=c};NativeEconomyUI.ShowCity(window);Check(!window.rows.ContainsKey("发行金币")&&window.rows.ContainsKey("god"),"stats have balances without duplicated controls");
  var owned=new KeyValueField();int clicked=0;NativeEconomyUI.BindAction(owned,()=>clicked++);Check(NativeEconomyUI.TryClick(owned)&&clicked==1,"editor action handles first touch");owned.on_click_value=()=>clicked+=10;Check(!NativeEconomyUI.TryClick(owned),"reused native row rejects stale owner");
  var other=City(3,12);var extra=City(30,36);other.kingdom.cities.Add(extra);var all=CurrencyScope.Cities(null,other.kingdom);
  Check(CurrencyScope.Apply(all,CurrencyScope.Operation.MintGold,1000)&&GodWorldRuntime.GetGold(other)==250&&GodWorldRuntime.GetGold(extra)==750,"nation issues once weighted by population");
  double nationalGold=CurrencyScope.Total(all,false);Check(!CurrencyScope.Apply(all,CurrencyScope.Operation.BurnGold,2000)&&CurrencyScope.Total(all,false)==nationalGold,"nation rejects insufficient burn without partial withdrawal");
  Check(CurrencyScope.Apply(all,CurrencyScope.Operation.BurnGold,1000)&&CurrencyScope.Total(all,false)==0,"nation burns from available cities");
  Check(CurrencyScope.Apply(all,CurrencyScope.Operation.MintGod,1000)&&CurrencyScope.Total(all,true)==1000,"nation issues god without multiplying amount");
  double nationalWorth=CurrencyScope.Total(all,true)*GodWorldRuntime.GetRate();Check(CurrencyScope.Apply(all,CurrencyScope.Operation.GodToGold,100)&&Math.Abs(CurrencyScope.Total(all,false)+CurrencyScope.Total(all,true)*GodWorldRuntime.GetRate()-nationalWorth)<1e-7,"nation exchange preserves wealth");
  var local=CurrencyScope.Cities(other,null);double extraGold=GodWorldRuntime.GetGold(extra);Check(CurrencyScope.Apply(local,CurrencyScope.Operation.MintGold,100)&&GodWorldRuntime.GetGold(extra)==extraGold,"village action stays local");
  var dust1=City(31,1);var dust2=City(32,1);GodWorldRuntime.Issue(dust1,true,.6);GodWorldRuntime.Issue(dust2,true,.4);var dust=new List<City>{dust1,dust2};Check(CurrencyScope.Apply(dust,CurrencyScope.Operation.BurnGod,1)&&CurrencyScope.Total(dust,true)<1e-9,"fractional god balances fund whole nationwide burn");
  var capped=City(33,1);GodWorldRuntime.Issue(capped,false,int.MaxValue);double localBefore=GodWorldRuntime.GetGold(other);Check(!CurrencyScope.Apply(new List<City>{other,capped},CurrencyScope.Operation.MintGold,100)&&GodWorldRuntime.GetGold(other)==localBefore,"nation capacity failure is atomic");
  var godCity=City(4,12);godCity.resources["wood"]=100;GodWorldRuntime.Issue(godCity,true,100);var buildCost=new ConstructionCost{wood=10};double godWorth=GodWorldRuntime.GetGold(godCity)+GodWorldRuntime.GetGod(godCity)*GodWorldRuntime.GetRate();GodWorldRuntime.EnsureBuildLiquidity(godCity,buildCost);Check(GodWorldRuntime.CanFundCost(godCity,buildCost,true),"god liquidity funds native construction");Check(Math.Abs(GodWorldRuntime.GetGold(godCity)+GodWorldRuntime.GetGod(godCity)*GodWorldRuntime.GetRate()-godWorth)<1e-7,"automatic conversion preserves wealth");
  var ledger=City(60,1);var worker=new Actor{city=ledger};ledger.units.Add(worker);worker.data.money=90;GodWorldRuntime.Issue(ledger,false,1000);
  double bank=GodWorldRuntime.GetGold(ledger);int income=GodWorldRuntime.FundNativeIncome(worker,100);worker.addLoot(income);Check(income==100&&worker.data.loot==100&&GodWorldRuntime.GetGold(ledger)==bank-100,"production prefunds native pending income exactly once");
  bank=GodWorldRuntime.GetGold(ledger);worker.data.money+=worker.data.loot;worker.data.loot=0;Check(GodWorldRuntime.GetGold(ledger)==bank,"native settlement does not charge city twice");
  var receiver=new Actor{city=ledger};int gift=GodWorldRuntime.PrepareGift(30,worker,receiver);receiver.data.money+=gift;Check(worker.data.money==160&&receiver.data.money==30&&GodWorldRuntime.GetGold(ledger)==bank,"gift transfers sender money without city charge");
  int self=GodWorldRuntime.PrepareGift(20,worker,worker);Check(self==0&&worker.data.money==160,"self gift does not create money");receiver.data.money=int.MaxValue-2;gift=GodWorldRuntime.PrepareGift(30,worker,receiver);Check(gift==2&&worker.data.money==158,"gift honors recipient capacity before debiting sender");
  int cash=worker.data.money;double coins=GodWorldRuntime.GetGold(ledger);GodWorldRuntime.SpendPolitics(worker,7);Check(worker.data.money==cash-7&&GodWorldRuntime.GetGold(ledger)==coins,"political expense leaves commercial wallet and public treasury alone");
  int research=NativeProgression.SkillLevel(worker,2);NativeProgression.AfterReading(worker,1);int raw;worker.data.get("god_skill_xp_2",out raw,0);Check(raw==0,"failed reading earns no research");NativeProgression.AfterReading(worker,0);worker.data.get("god_skill_xp_2",out raw,0);Check(raw==3,"completed native reading earns research");
  int snapshot=worker.data.money;World.world.map_stats.year++;GodWorldRuntime.TickCity(ledger,1);Check(worker.data.money==snapshot,"annual resident sample does not invent consumption or research payments");
  var unfunded=City(61,1);var unpaid=new Actor{city=unfunded};GodWorldRuntime.EarnNativeIncome(unpaid,10);Check(unpaid.data.loot==0&&GodWorldRuntime.GetGold(unfunded)==0,"unfunded production does not mint native income");
  var fundedGod=City(62,1);var dualWorker=new Actor{city=fundedGod};GodWorldRuntime.SetRate(2);GodWorldRuntime.Issue(fundedGod,true,10);int dualIncome=GodWorldRuntime.FundNativeIncome(dualWorker,6);Check(dualIncome==6&&GodWorldRuntime.GetGod(fundedGod)==7,"god funds native wages through current exchange rate");
  GodWorldRuntime.Flush();string ledgerState;ledger.data.get("godworld.economy.v2",out ledgerState,"");var state=Newtonsoft.Json.JsonConvert.DeserializeObject<GodEconomyState>(ledgerState);Check(state.politics.gold==7,"political fees persist separately");
  var legacy=City(63,1);legacy.data.set("godworld.economy.v2","{\"households\":{\"gold\":37},\"business\":{\"gold\":42}}");var legacyActor=new Actor{city=legacy};Check(GodWorldRuntime.FundNativeIncome(legacyActor,10)==10,"old saved payroll balance remains spendable");GodWorldRuntime.Flush();string legacyJson;legacy.data.get("godworld.economy.v2",out legacyJson,"");var migrated=Newtonsoft.Json.JsonConvert.DeserializeObject<GodEconomyState>(legacyJson);Check(migrated.households.gold==27&&migrated.business.gold==42&&migrated.education!=null&&migrated.military!=null&&migrated.politics!=null,"old save preserves balances and initializes new budgets");
  var publicFunds=City(70,10);GodWorldRuntime.SetRate(2);GodWorldRuntime.Issue(publicFunds,true,10);Check(GodWorldRuntime.EnsurePublicLiquidity(publicFunds,6)&&GodWorldRuntime.GetGold(publicFunds)==6&&GodWorldRuntime.GetGod(publicFunds)==7,"public procurement converts only missing god liquidity");
  Check(GodWorldRuntime.TryDebitPublic(publicFunds,4)&&GodWorldRuntime.GetGold(publicFunds)==2,"public procurement debits exactly once");double publicWorth=GodWorldRuntime.GetGold(publicFunds)+GodWorldRuntime.GetGod(publicFunds)*2;Check(!GodWorldRuntime.TryDebitPublic(publicFunds,100)&&GodWorldRuntime.GetGold(publicFunds)+GodWorldRuntime.GetGod(publicFunds)*2==publicWorth,"unaffordable procurement leaves both currencies unchanged");
  Check(!GodWorldRuntime.TryDebitPublic(publicFunds,-1),"negative public debit is rejected");Check(GodWorldRuntime.CreditPublic(publicFunds,3)&&GodWorldRuntime.GetGold(publicFunds)==5,"public refund credits actual treasury");GodWorldRuntime.CreditBusiness(publicFunds,4);Check(GodWorldRuntime.State(publicFunds).business.gold==4&&GodWorldRuntime.State(publicFunds).salesReceipts==4,"commercial payment records exactly one sale");
  Check(!GodWorldRuntime.CreditPublic(capped,1)&&GodWorldRuntime.GetGold(capped)==int.MaxValue,"refund capacity failure does not overflow treasury");
  var childrenOnly=City(71,20);childrenOnly.status.population_adults=0;childrenOnly.resources["wood"]=1000;GodWorldRuntime.Issue(childrenOnly,false,1000);World.world.map_stats.year++;GodWorldRuntime.TickCity(childrenOnly,1);Check(childrenOnly.getResourcesAmount("wood")==1000&&GodWorldRuntime.State(childrenOnly).infrastructure==0,"native children are not counted as industrial workers");
  var fighter=new Actor{city=publicFunds};double combatGod=GodWorldRuntime.GetGod(publicFunds);GodWorldRuntime.CombatWork(fighter);Check(Math.Abs(combatGod-GodWorldRuntime.GetGod(publicFunds)-.01)<1e-8,"completed combat grants one funded god reward");
  World.world.map_stats=new MapStats();Check(GodWorldRuntime.GetRate()==1,"new world has independent rate");Check(UnityEngine.Debug.warnings.Count==0,"no runtime adapter warnings");Console.WriteLine(checks+" native-adapter checks passed");
 }
}

